{
 "summary": "The Lean target asserts a linear list-Hadwiger bound. There is a constant C ≥ 1 such that every finite nonempty simple graph G satisfies ch(G) ≤ C·h(G), where ch is the list chromatic number and h is the Hadwiger number. The paper excerpt claims the opposite kind of result: it disproves Hadwiger's conjecture χ(G) ≤ h(G) by constructing counterexamples, and it proves no positive upper bound on any chromatic parameter in terms of h(G). The single most important caveat is that the formal statement is unrelated to, and of opposite polarity from, the paper's claims (goal substitution). The bespoke definitions themselves look faithful.",
 "glossary": [
  {"decl": "ListColorable", "line": 7, "plain": "There is a proper coloring c of G with c(v) ∈ L(v) for every vertex v.", "standard_concept": "L-colorability", "matches_standard": "yes", "note": ""},
  {"decl": "Choosable", "line": 11, "plain": "G is k-choosable: for every color type and every list assignment with |L(v)| ≥ k for all v, G is L-colorable.", "standard_concept": "k-choosability", "matches_standard": "yes", "note": "Colors are restricted to universe Type 0, which is harmless."},
  {"decl": "listChromaticNumber", "line": 14, "plain": "ch(G), the least k such that G is k-choosable (sInf).", "standard_concept": "list chromatic number (choice number)", "matches_standard": "yes", "note": "For finite G, k = |V| is choosable, so the set is nonempty and sInf is not a junk value."},
  {"decl": "HasCliqueMinor", "line": 17, "plain": "G has t branch sets that are pairwise disjoint and induce connected (hence nonempty) subgraphs, with an edge between every pair of them; that is, a K_t minor.", "standard_concept": "K_t minor", "matches_standard": "yes", "note": ""},
  {"decl": "hadwigerNumber", "line": 23, "plain": "h(G), the supremum of t such that G has a K_t minor.", "standard_concept": "Hadwiger number", "matches_standard": "yes", "note": "Branch sets are nonempty and disjoint, so t ≤ |V|; the set is bounded and contains 1 when V is nonempty."}
 ],
 "lean_claims": [
  {"theorem": "main_theorem", "line": 30, "plain": "There exists a natural number C ≥ 1 such that for every finite nonempty vertex type V and every simple graph G on V, ch(G) ≤ C·h(G)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For arbitrarily large m there is an m-vertex graph G with α(G) ≤ 2 and cm(G) < m/100."},
  {"ref": "Corollary 1.2", "plain": "There are graphs of arbitrarily large order m with h(G) < 26m/75 + 2/3 < m/2 ≤ χ_f(G) ≤ χ(G). Hence Hadwiger's conjecture and its fractional weakening are false."},
  {"ref": "Proposition 3.5 (stated in intro)", "plain": "h(G) ≤ (|V(G)| + 4·cm(G) + 2)/3."}
 ],
